from pathlib import Path

import yaml

_GAZETTEER_PATH = Path(__file__).resolve().parent.parent / "gazetteer.yaml"


def _stations_brief() -> str:
    data = yaml.safe_load(_GAZETTEER_PATH.read_text(encoding="utf-8"))
    lines = []
    for s in data["stations"]:
        aliases = ", ".join(s["brand_aliases"] + s["location_aliases"]) or "—"
        default_note = " [по умолчанию для бренда, если в тексте нет адреса ни одной его точки]" if s.get("default_for_brand") else ""
        lines.append(
            f"- id={s['id']}: {s['name']}, бренд «{s['brand']}», адрес: {s['address'] or '—'}, "
            f"локальные названия/алиасы: {aliases}{default_note}"
        )
    return "\n".join(lines)


def build_system_prompt() -> str:
    return f"""Ты разбираешь сообщения из тематического VK-чата про заправку топливом во время дефицита бензина в городе.

Раздели сообщение на:
- report — отчёт о наличии топлива и/или очереди, и/или о техническом перерыве (слив бензовоза/отстой топлива/тех перерыв) на конкретной АЗС
- question — вопрос о наличии топлива/очереди, и/или о техническом перерыве на АЗС (вопросительный знак не обязателен, "Подскажите, есть ли 92" тоже вопрос). Вопрос про перерыв не обязан называть конкретную марку — "есть ли у кого сведения о перерывах на заправках Роснефти?" тоже question, даже без марки топлива (см. пример 12).
- irrelevant — не по теме, либо по теме, но без конкретного факта о статусе хотя бы одной марки топлива И без упоминания технического перерыва (благодарности, вопросы про цену/лимит литров, реплики не по делу). Важно: если факт о марке ЕСТЬ, но станция не резолвится (нет в списке ниже, или бренд/адрес неоднозначны) — это всё равно report со station_id=null, а не irrelevant (см. пример 2). Аналогично для перерыва: вопрос или отчёт про перерыв БЕЗ марки топлива и/или без резолвящейся станции — всё равно question/report со station_id=null, а не irrelevant (см. примеры 8 и 12).

Список известных АЗС:
{_stations_brief()}

Правила:
- station_id — только id из списка выше, если уверен; если бренд упомянут без адреса, а у бренда несколько точек в списке, или станции вообще нет в списке — верни null, не угадывай. Исключение: если у бренда есть точка с пометкой "по умолчанию" (см. список) — голое упоминание бренда без адреса резолвится в неё (см. пример 3).
- Если бренд вообще не упомянут, но есть локация/адрес, совпадающий с алиасом ровно ОДНОЙ станции из списка — резолви по ней (см. пример 5). Если такая локация — алиас у нескольких станций (например "на объездной" встречается у станций разных брендов) — тоже null, не угадывай, какой бренд имелся в виду. Это правило — только когда бренд НЕ упомянут вовсе: если бренд в сообщении назван явно, резолвь строго среди станций этого бренда по его собственным алиасам, даже если рядом есть локация, которая как алиас принадлежит другой станции/бренду — не переключайся на другой бренд, это не тот случай.
- Опечатки и склонения бренда/адреса не должны мешать — сопоставляй по смыслу (например "газпропе" это опечатка "газпроме").
- В report извлекай КАЖДУЮ упомянутую марку топлива со статусом: отрицание ПЕРЕД маркой ("нет 95-го", "закончился 92") — unavailable, обычное упоминание/наличие ("95 есть", "только 92 на табло") — available. Осторожно с порядком слов: "92 нет очереди" — это про очередь ("нет" относится к очереди, а не к марке), 92 при этом available, а не unavailable; это верно и для более длинных фраз ("92 нет очереди на остальных колонках" — по-прежнему про очередь, см. пример 6). Общая фраза про очередь отдельным предложением ("очередь медленно идёт", "очередь большая") относится к очереди в целом и не делает недоступной ни одну из упомянутых рядом марок.
- "Марка X только на такой-то колонке" — это про то, где именно её видели, а НЕ сигнал, что другие марки недоступны на прочих колонках (если про них ничего плохого не сказано отдельно — они available, см. пример 6).
- В question извлекай марки, о которых спрашивают (question_grades), список может быть пустым, если вопрос без привязки к марке.
- queue_note — короткая заметка про очередь на русском ("без очереди", "~12 мин", "есть очередь") или null, если не упоминалась.
- Если перед текущим сообщением есть блок «Предыдущее сообщение того же автора» — это только подсказка для разрешения неявных ссылок (станция/марка не названы явно в текущем сообщении), само оно не разбирается и не становится частью ответа. Всё, что ты возвращаешь, должно описывать только то, что идёт после «Текущее сообщение (разобрать именно его):» — не оба сообщения вместе (см. пример 7).
- break_info — только для report: технический перерыв/слив бензовоза на станции (kind: "слив"/"отстой"/"перерыв", until: ЧЧ:ММ если время окончания названо явно, duration_note: свободный текст длительности, если точного времени нет). Для question всегда null — ответ про активный перерыв строится из уже сохранённых данных, а не из текста вопроса (см. пример 11). Сообщение только о перерыве, без единой марки топлива — это всё равно report с пустым reports, а не irrelevant (см. пример 8), точно так же, как факт о марке без резолвящейся станции — report, а не irrelevant. Формулировки про будущее ("появится через час", "скоро привезут") не делают марку available прямо сейчас — не записывай их в reports как текущий факт (см. пример 10).

Примеры разбора:
1. "РН лесной, 95 есть на 4,5 колонке. Очередь." → report, station_id=rosneft_lesnoy_79, reports=[{{"grade":"95","status":"available"}}], queue_note="есть очередь"
2. "Нет 95го в пряже\\n92 и ДТ" → report, station_id=null (Пряжа — посёлок, не АЗС из списка), reports=[{{"grade":"95","status":"unavailable"}},{{"grade":"92","status":"available"}},{{"grade":"ДТ","status":"available"}}], queue_note=null
3. "на газпропе есть 95?" → question, station_id=gazprom (опечатка "газпроме"; у бренда две точки, но своего адреса ни у одной в тексте нет — резолвим в станцию "по умолчанию"), question_grades=["95"]
4. "Спасибо, заправилась)" → irrelevant, station_id=null, reports=[], question_grades=[], queue_note=null
5. "Есть 92 в вилге?" → question, station_id=lukoil_vilga (бренд не упомянут, но "вилге" — уникальный алиас именно этой станции), question_grades=["92"]
6. "95 только на 1 и 2 колонке. 92 нет очереди на остальных колонках." → report, reports=[{{"grade":"95","status":"available"}},{{"grade":"92","status":"available"}}], queue_note=null (обе марки available: "только на 1 и 2 колонке" — это про расположение 95, не про недоступность 92; "92 нет очереди" — снова про очередь, не про марку)
7. "Предыдущее сообщение того же автора (только для контекста, само по себе не разбирать): 95 есть на Газпроме?\\nТекущее сообщение (разобрать именно его): большая очередь?" → question, station_id=gazprom (станция не названа в текущем сообщении, но следует из предыдущего сообщения того же автора), question_grades=[], queue_note=null
8. "Слив бензовоза на Лукойле Вилга, минут 40" → report, station_id=lukoil_vilga, reports=[], queue_note=null, break_info={{"kind":"слив","until":null,"duration_note":"минут 40"}} (нет ни одной марки топлива, но это всё равно report, не irrelevant — есть факт о перерыве)
9. "Тех перерыв на Газпроме до 22:00" → report, station_id=gazprom, reports=[], queue_note=null, break_info={{"kind":"перерыв","until":"22:00","duration_note":null}}
10. "слив бензовоза, 95 появится через час" → report, station_id=null (станция не названа), reports=[], queue_note=null, break_info={{"kind":"слив","until":null,"duration_note":"через час"}} ("появится через час" — прогноз на будущее, не текущий статус, поэтому 95 НЕ попадает в reports как available)
11. "Будет тех перерыв на РН на Лососинском с 21-22 ч?" → question, station_id=rosneft_lososinskoe, question_grades=[], queue_note=null, break_info=null (это вопрос про перерыв, не отчёт о нём — break_info не заполняется даже несмотря на упомянутое время)
12. "Подскажите есть ли у кого сведения о перерывах на заправках Роснефти?(без учета слива бензовоза) Когда пересменки и другие перерывы?" → question, station_id=null (бренд назван, но конкретная точка не уточнена — общий вопрос сразу про все точки бренда), question_grades=[], queue_note=null, break_info=null (это question, не irrelevant — вопрос про перерыв без марки топлива всё равно на тему)
"""


def build_user_content(text: str, *, previous_message: str | None = None) -> str:
    """Тело пользовательского сообщения для LLM. Без предыдущего сообщения —
    просто текст как есть; с ним — оба сообщения размечены явно, чтобы
    модель не путала контекст с тем, что нужно разобрать (см. правило про
    предыдущее сообщение в build_system_prompt)."""
    if not previous_message:
        return text
    return (
        f"Предыдущее сообщение того же автора (только для контекста, "
        f"само по себе не разбирать): {previous_message}\n"
        f"Текущее сообщение (разобрать именно его): {text}"
    )
